import { useRef, useState } from "react";

export function Throttling({
  intervalMs = {{intervalMs}},
  buttonLabel = "{{buttonLabel}}",
  accent = "{{accent}}",
  showInterval = {{showInterval}},
}) {
  const [clicks, setClicks] = useState(0);
  const [ran, setRan] = useState(0);
  const last = useRef(0);
  const onClick = () => {
    setClicks((c) => c + 1);
    const now = Date.now();
    if (now - last.current >= intervalMs) {
      last.current = now;
      setRan((r) => r + 1);
    }
  };
  return (
    <div style={{ font: "13px/1.5 system-ui, sans-serif", color: "#241430", background: "#FAF7F2", padding: 18, borderRadius: 12, width: 300, boxSizing: "border-box" }}>
      <button type="button" onClick={onClick} style={{ display: "block", width: "100%", border: "none", padding: 12, borderRadius: 8, fontWeight: 600, fontSize: 13, color: "#241430", cursor: "pointer", marginBottom: 8, background: accent }}>{buttonLabel}</button>
      {showInterval && <p style={{ margin: "0 0 8px", fontSize: 10, color: "#24143099" }}>Handler runs at most once every {intervalMs}ms</p>}
      <p role="status" style={{ margin: 0, fontSize: 12, fontWeight: 600 }}>clicks: {clicks} &nbsp; handler ran: {ran}</p>
    </div>
  );
}
